// Shared RSS helpers for the publish and health-check scripts. String matching
// keeps them dependency-free; the feeds are generated by our own Worker, so
// their shape is known.

export function parseItems(xml) {
	return [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => {
		const block = m[1];
		const title = (block.match(/<title>([\s\S]*?)<\/title>/) || [])[1] ?? '';
		const url = (block.match(/<link>([\s\S]*?)<\/link>/) || [])[1] ?? '';
		return { title, url };
	});
}

// Compares two feeds by article URL. `missing` are source articles absent from
// the published feed; `extra` are published articles the source has dropped.
export function compareFeeds(sourceItems, publishedItems) {
	const sourceUrls = new Set(sourceItems.map((i) => i.url));
	const publishedUrls = new Set(publishedItems.map((i) => i.url));
	const missing = [...sourceUrls].filter((u) => !publishedUrls.has(u));
	const extra = [...publishedUrls].filter((u) => !sourceUrls.has(u));
	return { inSync: missing.length === 0 && extra.length === 0, missing, extra };
}
